LISTS.append(('ROM', 'Rise of Macedon (Alexander the Great)', 'Rise_of_Macedon_Alexander.cat', ROM, ROM_V, ROM_NOTES))
LISTS.append(('IMP', 'Alexandrian Imperial (Alexander the Great)', 'Alexandrian_Imperial_Alexander.cat', IMP, IMP_V, IMP_NOTES))
