def IWM(name, pts, t, w, extra=0):
    ms = [M(name, f'- - - - {t} {w} - - -', pts, key='machine'), M('Crew', '4 3 3 3 3 1 3 1 7', 0, mn=2, mx=2, key='crew', weapons=['Broadsword'])]
    if extra: ms.append(M('Extra Crewman', '4 3 3 3 3 1 3 1 7', 7, mn=0, mx=1, key='xcrew', weapons=['Broadsword']))
    return U(SPT, name, ms, {'Light Ballista': 'Light Bolt Thrower (ballista): Range 36", Strength 4/-1 per rank, no save, D3 wounds per hit.', 'Heavy Ballista': 'Heavy Bolt Thrower (ballista): Range 48", Strength 5/-1 per rank, no save, D4 wounds per hit. One extra crewman +7 pts.', 'Stone Thrower': 'Stone Thrower: Range 48", Strength 7, no save, D3 wounds per hit. One extra crewman +7 pts. May only be used in sieges.'}[name] + ' Each machine has a crew of two men armed with broadsword. Up to one war machine is allowed for each bodyguard, hereditary or mercenary infantry unit in the army. War machines may be grouped in batteries of up to three models. Classical, Mountain and Republican lists: war machines (other than the Rathamasaula) only in sieges.', page='110')
IN.append(IWM('Light Ballista', 40, 5, 2)); IN.append(IWM('Heavy Ballista', 50, 6, 2, 1)); IN.append(IWM('Stone Thrower', 75, 7, 3, 1))
IN.append(U(SPT, 'Rathamasaula', [M('Rathamasaula', '- - - 4 4 3 - - -', 76, key='machine', rules=['Rathamasaula']), M('Crewman', '4 4 4 3 3 1 3 1 8', 0, mn=4, mx=4, key='crew', weapons=['Broadsword'], options=[('Light armour', 4)])],
    'Man-pushed anti-elephant war cart. The four warrior crewmen are armed with broadswords. The crewmen may have light armour +4 pts each. When it charges it causes no impact hits against normal troops, however against elephants the cart inflicts D3 wounds with no saves allowed. It charges up to 8" depending on remaining crewmen, cannot march move. The crews may not fight when it charges. If charged the crew defend from behind the Rathamasaula and are -1 to hit. A war machine. Classical and Mauryan lists (included more for fun than anything else).', page='111'))
IN.append(U(SPT, 'War Wagons', [M('War Wagon', '5 - - 5 4 3 1 2 -', 96, key='wagon', rules=['War Wagons']),
    M('Warrior Crewman', '4 4 4 3 3 1 3 1 8', 0, mn=2, mx=2, key='crew', weapons=['Broadsword', 'Javelin', 'Longbow'], options=[('Exchange longbow for shield', 0), ('Exchange longbows for bows (+3 per crewman)', 3), ('Light armour', 4)]),
    M('Shield Bearer', '4 3 3 3 3 1 3 1 6', 0, mn=2, mx=2, key='sb', weapons=['Broadsword', 'Javelin', 'Shield'])],
    'Warrior crewmen are armed with broadsword, javelins, longbow or shield. The warriors may replace longbows with bows +3 pts each. Shield bearers are armed with broadswords, javelins, and shield. Any crew may have light armour +4 pts. War Wagons: pulled by two or more oxen, and crewed by one unarmed driver, two shield bearers, and two warriors. War Wagons are treated as Heavy chariots, however they do not cause fear in infantry. Their lumbering gait will not allow double moves or inflict impact hits when they charge. The wagon may engage elephants and the crew do not fear elephants. The wagon\'s attacks represent the oxen: front only, hits only on 6s. Crewmen attack separately; models fighting from inside a wagon gain a 5+ save. War Wagons are not allowed in armies that include elephants, or large chariots. Each wagon is counted as a single model. Crews may not have standards, musicians or leaders. Not allowed in the Classical or Mountain lists.', page='111'))
IN.append(U(SPT, 'Wagons (Laager)', [M('Wagon', '- - - - 4 3 - - -', 35, mn=5, key='wagon', rules=['Wagon Laager (Republican)'])],
    'Special Troops (Republican Indian list only). Wagons are fielded in groups of five models minimum, each wagon is treated as a single model (based 60mm by 40mm). They may be deployed up to 12" from the player\'s baseline, end-to-end in a single straight line parallel to the baseline. The wagons may not be moved and are immune to psychology and cannot be broken in hand-to-hand combat. The line counts as a wall 40mm wide; each wagon model may be occupied by up to four infantry skirmishers, or characters. Units behind wagons count as in soft cover but may not use massed archery; wagons count as large targets; defenders in wagons gain a 5+ save like chariots. Attackers need 6s to hit units behind unoccupied wagons or skirmishers inside them, until the attacker wins a round of combat. Empty and undefended wagons are destroyed at the end of the Combat phase if an enemy unit of five models or more remains in contact.', page='114'))
